@MainActor
final class SessionSnapshotTests: XCTestCase {
    func testReadySnapshot() throws {
        let app = XCUIApplication()
        app.launchArguments = ["--ui-testing", "--fixture=session-ready"]
        app.launch()
        let state = app.staticTexts["session.state"]
        XCTAssertTrue(waitForText("Готово", element: state))
        let shot = app.screenshot()
        let attachment = XCTAttachment(screenshot: shot)
        attachment.lifetime = .keepAlways
        add(attachment)
        let bundle = Bundle(for: SessionSnapshotTests.self)
        let path = try XCTUnwrap(bundle.url(
            forResource: "session-ready", withExtension: "png"
        ))
        let reference = try XCTUnwrap(UIImage(contentsOfFile: path.path))
        XCTAssertEqual(try raster(shot.image), try raster(reference))
    }
}

Сравниваются размеры и декодированные RGBA-пиксели; отсутствие файла тоже провал теста. Эталон и среда — условия задачи, они не создавались и не проверялись запуском в этом пакете.

